package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TokenBuffer_writeNumber_TriageGen0Test {

    private TokenBuffer tokenBuffer;
    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        // Using the constructor that takes an ObjectCodec
        tokenBuffer = new TokenBuffer(mapper);
    }

    /**
     * Tests that passing null to writeNumber calls writeNull().
     * This covers the if (v == null) branch.
     */
    @Test
    public void testWriteNumber_Null() throws IOException {
        tokenBuffer.writeNumber((BigInteger) null);

        // Verify the token is indeed VALUE_NULL
        Assert.assertEquals(JsonToken.VALUE_NULL, tokenBuffer.firstToken());
    }

    /**
     * Tests that passing a valid BigInteger calls _append with VALUE_NUMBER_INT.
     * This covers the else branch.
     */
    @Test
    public void testWriteNumber_ValidBigInteger() throws IOException {
        BigInteger val = new BigInteger("123456789012345678901234567890");
        tokenBuffer.writeNumber(val);

        // Verify the token is VALUE_NUMBER_INT
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, tokenBuffer.firstToken());

        // To verify the actual value, we can use a JsonParser to read it back
        JsonParser parser = tokenBuffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        Assert.assertEquals(val, parser.getBigInteger());
    }

    /**
     * Tests with a zero value.
     */
    @Test
    public void testWriteNumber_Zero() throws IOException {
        BigInteger val = BigInteger.ZERO;
        tokenBuffer.writeNumber(val);

        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, tokenBuffer.firstToken());
        JsonParser parser = tokenBuffer.asParser();
        parser.nextToken();
        Assert.assertEquals(val, parser.getBigInteger());
    }

    /**
     * Tests with a negative value.
     */
    @Test
    public void testWriteNumber_Negative() throws IOException {
        BigInteger val = new BigInteger("-98765432109876543210");
        tokenBuffer.writeNumber(val);

        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, tokenBuffer.firstToken());
        JsonParser parser = tokenBuffer.asParser();
        parser.nextToken();
        Assert.assertEquals(val, parser.getBigInteger());
    }
}
